mapper.select:
SELECT mbwr.id AS 'id', mbwr.product_type as 'productType', mbwr.warehouse_record_id AS 'mesBuildingWarehouseRecordId', ta.project_id AS 'projectId', monomer.id AS 'monomerId', monomer.NAME AS 'monomerName', area.id AS 'areaId', area.NAME AS 'areaName', ta.id AS 'productId', ta.name as 'productName', ta.serial_number as 'serialNumber', ta.specification as 'specification', ROUND(ta.length / 1000, 3) as 'length', ta.material as 'material', mbwr.quantity as 'quantity', mbwr.net_weight, mbwr.gross_weight FROM mes_building_cargo_list cargo LEFT JOIN mes_building_cargo_list_product_link mbwr ON mbwr.cargo_list_id = cargo.id LEFT JOIN tech_artifact ta ON mbwr.product_id = ta.id LEFT JOIN plan_monomer monomer ON ta.monomer_id = monomer.id AND monomer.bool_delete_enum = 0 LEFT JOIN plan_area area ON ta.area_id = area.id AND area.bool_delete_enum = 0 where mbwr.bool_delete_enum = 0 AND mbwr.product_type = 2 AND mbwr.warehouse_type in(0, 2) AND cargo.bool_delete_enum = 0 AND cargo.status in(4, 8)
and ta.project_id = #{projectId}
and ta.monomer_id = #{monomerId}
and ta.area_id = #{areaId}
and ta.name like concat('%', #{name}, '%')
and ta.serial_number like concat('%', #{serialNumber}, '%')
and ta.specification like concat('%', #{specification}, '%')
and ta.material like concat('%', #{material}, '%')
ORDER BY mbwr.create_time DESC

SELECT mbwr.id, mbwr.warehouse_record_id AS mes_building_warehouse_record_id, mbwr.product_type, tsp.project_id, tsp.NAME AS product_name, monomer.id AS monomer_id, monomer.NAME AS monomer_name, area.id AS area_id, area.NAME AS area_name, tsp.enclosure_plan_id AS plan_id, ep.name AS plan_name, tsp.id AS 'productId', tsp.specification , mbwr.quantity , tsp.measure_unit, CASE tsp.bool_weight_type_enum WHEN 1 THEN mbwr.weight * mbwr.quantity ELSE CONVERT(IFNULL(tsp.mete, 0) / tsp.quantity, DECIMAL(18,4)) * mbwr.quantity END 'mete', CASE tsp.bool_weight_type_enum WHEN 1 THEN mbwr.weight ELSE CONVERT(IFNULL(tsp.mete, 0) / tsp.quantity, DECIMAL(18,4)) END 'singleMete', tsp.accounting_unit AS 'accountingUnit' FROM mes_building_cargo_list cargo INNER JOIN mes_building_cargo_list_product_link mbwr ON mbwr.cargo_list_id = cargo.id LEFT JOIN tech_standard_part tsp ON mbwr.product_id = tsp.id AND tsp.bool_delete_enum = 0 LEFT JOIN plan_monomer monomer ON tsp.monomer_id = monomer.id LEFT JOIN plan_area area ON tsp.area_id = area.id LEFT JOIN enclosure_plan ep ON tsp.enclosure_plan_id = ep.id WHERE mbwr.bool_delete_enum = 0 AND tsp.relation_type = 2 AND mbwr.product_type = 8 AND mbwr.warehouse_type in(0,2) AND cargo.bool_delete_enum = 0 AND cargo.status in(4,8)
and tsp.project_id = #{projectId}
and tsp.monomer_id = #{monomerId}
and tsp.area_id = #{areaId}
and tsp.enclosure_plan_id = #{planId}
and tsp.name like concat('%', #{name}, '%')
and tsp.serial_number like concat('%', #{serialNumber}, '%')
and tsp.specification like concat('%', #{specification}, '%')
and tsp.material like concat('%', #{material}, '%')
ORDER BY mbwr.create_time DESC
